      const ws = { id: `ss-${now.toString(36)}`, kind: KIND, command: `${verb} ${body}`.slice(0, 120), name: name.toLowerCase(), amount_cents: cents, at_date: w.day, at_hour: w.hour, at_min: w.min, created_on: nl.date, status: "active" };
