    const STATUS = /^(?:how close am i to |where am i (?:on|with) |progress on |how(?:'s|s| is| are)? |show(?: me)? |check |what's |whats )?(?:my |the )?(?:([a-z][a-z' -]{0,24}?) )?(?:savings )?(?:fund|goal)s?(?: (?:doing|looking|going|coming along|at|progress|status))?$/;
