    const have = expected.map(e => { const d = (ctx.docs || []).find(x => x.kind === "tax_form" && x.subkind === e.form && slug(x.issuer) === slug(e.issuer) && Number(x.year) === Number(year)); return { ...e, doc: d || null, file: fileName(year, e.form, e.issuer) }; });
